import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { join } from "node:path";
import type { APIRoute } from "astro";
import { adminDist } from "../admin.ts";

export const prerender = false;

const dist = adminDist(createRequire(import.meta.url).resolve);

/** Production SVG sprite generated by `zero-icons` in the admin package. */
export const GET: APIRoute = async () => {
	try {
		return new Response(await readFile(join(dist, "icons.svg")), {
			headers: {
				"content-type": "image/svg+xml",
				"x-content-type-options": "nosniff",
				"cache-control": "public, max-age=31536000, immutable",
			},
		});
	} catch {
		return new Response("Not found", { status: 404 });
	}
};
